function Score({ score }) {
	const { homeTeamLogo, homeTeam, result, awayTeam, awayTeamLogo } = score;
	return (
		<tr className="result-score-tr">
			<td></td>
			<td className="result-score-td">
				<img className="club-img" src={homeTeamLogo} alt={homeTeam} />
				{homeTeam}
			</td>
			<td className="result-score-td">{result}</td>
			<td className="result-score-td">
				{awayTeam}

				<img className="club-img" src={awayTeamLogo} alt={awayTeam} />
			</td>
			<td></td>
		</tr>
	);
}
export default Score;
